(4836652, 701324, 51793, '<td valign="top">I think your lighting and setup are a bit off. Try to watch out for glare from windows and other light sources. Try to get it to work for you instead of against you.</td>', 'I think your lighting and setup are a bit off. Try to watch out for glare from windows and other light sources. Try to get it to work for you instead of against you.', '2008-07-21 11:00:24.000000', NULL, 1),
(4836654, 700645, 51793, '<td valign="top">The lighting in the front of the pile looks about 1 stop darker than the one in the back and all still looks a tad under exposed. Also the scene is very cluttered. Should you have zoomed more in and filled the frame it would have been even better. Good luck</td>', 'The lighting in the front of the pile looks about 1 stop darker than the one in the back and all still looks a tad under exposed. Also the scene is very cluttered. Should you have zoomed more in and filled the frame it would have been even better. Good luck', '2008-07-21 11:02:26.000000', NULL, 1),
(4836656, 701145, 51793, '<td valign="top">This is a cute picture but I think you should have cleaned up the background some more with an adjustment layer. Good luck</td>', 'This is a cute picture but I think you should have cleaned up the background some more with an adjustment layer. Good luck', '2008-07-21 11:03:19.000000', NULL, 1),
