(4837245, 701159, 58691, '<td valign="top">Wow, you''ve realistically recreated aquatic life in a glass of soda. Truly brilliant. The large solitary bubble in the center nearing the surface (and the subsequent ones in the background on the left) seems to be the purpose of the "corals" existence - release oxygen. There is a stratigraphy here that is very fitting to the ocean/sea illusion. That is the light at the surface and the darkness in the depths. That gradation of light follows the activity upward through the entire image. Additionally, the tines and their chaotic movement give additional inward depth to the image. Wonderful capture.</td>', 'Wow, you''ve realistically recreated aquatic life in a glass of soda. Truly brilliant. The large solitary bubble in the center nearing the surface (and the subsequent ones in the background on the left) seems to be the purpose of the "corals" existence - release oxygen. There is a stratigraphy here that is very fitting to the ocean/sea illusion. That is the light at the surface and the darkness in the depths. That gradation of light follows the activity upward through the entire image. Additionally, the tines and their chaotic movement give additional inward depth to the image. Wonderful capture.', '2008-07-21 17:28:37.000000', NULL, 1),
(4837266, 700737, 68599, '<td valign="top">Love the title :) As for the picture, it''s pretty awesome as well. I think it''s a bit of a stretch to say it meets the challenge, but i like creativity of the title so much i''ll give it a 7 :)</td>', 'Love the title :) As for the picture, it''s pretty awesome as well. I think it''s a bit of a stretch to say it meets the challenge, but i like creativity of the title so much i''ll give it a 7 :)', '2008-07-21 17:39:31.000000', NULL, 1),
(4837268, 700246, 68599, '<td valign="top">Nice composition and lighting.</td>', 'Nice composition and lighting.', '2008-07-21 17:39:54.000000', NULL, 1),
(4837275, 701116, 67553, '<td valign="top">I really like the texture that the foam gives to the splash in this one.  The centered composition and slight blurring of the splash at the top detract however.</td>', 'I really like the texture that the foam gives to the splash in this one.  The centered composition and slight blurring of the splash at the top detract however.', '2008-07-21 17:50:35.000000', NULL, 1),
(4837287, 701315, 58691, '<td valign="top">I keep staring at this image and am amazed at all of the detail, texture, emotion and feeling in a powdered donut. While drawn to the center in-focus part of the donut, and the in-focus bit of sugar that has fallen off, the image still guides the eye around the frame and warrants an investigation and study of other other parts of the image and the composition as a whole.</td>', 'I keep staring at this image and am amazed at all of the detail, texture, emotion and feeling in a powdered donut. While drawn to the center in-focus part of the donut, and the in-focus bit of sugar that has fallen off, the image still guides the eye around the frame and warrants an investigation and study of other other parts of the image and the composition as a whole.', '2008-07-21 17:56:51.000000', NULL, 1),
(4837295, 701326, 67553, '<td valign="top">I''m not getting this one.  It''s a rose with sugar on it.  Why?  Still. . . You have captured the rose exquisitely, and the red really pops.  <br/> <br/>In this case, I think the sugar globbed all over the rose detracts from the image.  I think ''rose'' when I see this, not ''sugar''.</td>', 'I''m not getting this one.  It''s a rose with sugar on it.  Why?  Still. . . You have captured the rose exquisitely, and the red really pops.   In this case, I think the sugar globbed all over the rose detracts from the image.  I think ''rose'' when I see this, not ''sugar''.', '2008-07-21 18:00:53.000000', NULL, 1),
(4837298, 701270, 67553, '<td valign="top">Simple.  Clean.  Well lit.  Nice, I like it.</td>', 'Simple.  Clean.  Well lit.  Nice, I like it.', '2008-07-21 18:02:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4837303, 699642, 67553, '<td valign="top">I like the juxtaposition of the serious looking adult with something I remember fondly from my carefree childhood.  The B&amp;W processing works well for this shot as well.</td>', 'I like the juxtaposition of the serious looking adult with something I remember fondly from my carefree childhood.  The B&W processing works well for this shot as well.', '2008-07-21 18:04:35.000000', NULL, 1),
(4837314, 701296, 67553, '<td valign="top">I''m not sure that black was the proper background color for this one.  It gives what should be a cheery, lighthearted image more of a brooding disposition.</td>', 'I''m not sure that black was the proper background color for this one.  It gives what should be a cheery, lighthearted image more of a brooding disposition.', '2008-07-21 18:11:57.000000', NULL, 1),
(4837316, 699568, 67553, '<td valign="top">Great texture, and I find that the DOF with the OOF crystals gives this a sense of motion, making for a dynamic composition.  Nicely done.</td>', 'Great texture, and I find that the DOF with the OOF crystals gives this a sense of motion, making for a dynamic composition.  Nicely done.', '2008-07-21 18:13:45.000000', NULL, 1),
(4837324, 701222, 67553, '<td valign="top">Yum!  Nice processing on this one, and I like the composition with the face on the bottom of the frame.  I would have preferred to see the eyes open for a more sensuous/decadent look, and I''m still looking to try and figure out what the reflections in the chocolate are.  :)  Overall, one of my favorite shots in this challenge.</td>', 'Yum!  Nice processing on this one, and I like the composition with the face on the bottom of the frame.  I would have preferred to see the eyes open for a more sensuous/decadent look, and I''m still looking to try and figure out what the reflections in the chocolate are.  :)  Overall, one of my favorite shots in this challenge.', '2008-07-21 18:18:44.000000', NULL, 1),
(4837329, 701216, 67553, '<td valign="top">Green yellow and orange reminds me of my parent''s kitchen back in the 70''s.  :)<br/> <br/>Why a cricket?  I don''t think ''sugar'' when I see this image, rather I focus on the cricket.  Compositionally, I think cropping the right hand side and bottom in tighter to provide more of a rule of thirds could have improved it.</td>', 'Green yellow and orange reminds me of my parent''s kitchen back in the 70''s.  :) Why a cricket?  I don''t think ''sugar'' when I see this image, rather I focus on the cricket.  Compositionally, I think cropping the right hand side and bottom in tighter to provide more of a rule of thirds could have improved it.', '2008-07-21 18:25:28.000000', NULL, 1),
(4837335, 700371, 67553, '<td valign="top">I really like this one overall, with the colors, tone, DOF, composition. . .   I do find the bottom quarter of the image distracting though, being as OOF as it is.</td>', 'I really like this one overall, with the colors, tone, DOF, composition. . .   I do find the bottom quarter of the image distracting though, being as OOF as it is.', '2008-07-21 18:28:23.000000', NULL, 1),
(4837339, 700351, 73452, '<td valign="top">yum!  looks really tasty, and really unhealthy! haha</td>', 'yum!  looks really tasty, and really unhealthy! haha', '2008-07-21 18:29:52.000000', NULL, 1),
