INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4840761, 699642, 3087, '<td valign="top">Ha, this is fun! I love those candy cigarettes. You can still buy them in my local newsagents but they have to call them candy sticks now otherwise they are deemed to be glamourising smoking to young kiddies! So they don''t have the bright coloured end (which was meant to mimic the glowing ciggie end). Oh well!</td>', 'Ha, this is fun! I love those candy cigarettes. You can still buy them in my local newsagents but they have to call them candy sticks now otherwise they are deemed to be glamourising smoking to young kiddies! So they don''t have the bright coloured end (which was meant to mimic the glowing ciggie end). Oh well!', '2008-07-23 10:49:40.000000', NULL, 1),
(4840764, 701110, 3087, '<td valign="top">I love the intense colours, the smooth, bulging surface held together by surface tension, the lovely liquid-saturated sugar cube with such fine detail of the crystals and that little drop below turned into molten gold by the light falling through it. Great composition, great sharpness, lovely contrast. All good.</td>', 'I love the intense colours, the smooth, bulging surface held together by surface tension, the lovely liquid-saturated sugar cube with such fine detail of the crystals and that little drop below turned into molten gold by the light falling through it. Great composition, great sharpness, lovely contrast. All good.', '2008-07-23 10:51:02.000000', NULL, 1),
(4840768, 701327, 3087, '<td valign="top">Ooooh, I likey. This is just lovely. I think the shadow or vignette at the lower right is a bit too strong but otherwise, wouldn''t change a thing.</td>', 'Ooooh, I likey. This is just lovely. I think the shadow or vignette at the lower right is a bit too strong but otherwise, wouldn''t change a thing.', '2008-07-23 10:52:19.000000', NULL, 1),
(4840769, 701305, 3087, '<td valign="top">Nice high-key image.</td>', 'Nice high-key image.', '2008-07-23 10:53:01.000000', NULL, 1),
(4840771, 701329, 66494, '<td valign="top">Oh my, you''ve chosen my absolute favorite sweet ... and I''m in the middle of a very successful diet ... it just isn''t fair!!  7</td>', 'Oh my, you''ve chosen my absolute favorite sweet ... and I''m in the middle of a very successful diet ... it just isn''t fair!!  7', '2008-07-23 10:54:12.000000', NULL, 1),
(4840930, 701227, 94614, '<td valign="top">Extremely well shot- and EXTREMELY cute- great colors, focus- everything works for me :) adding to my favorites!</td>', 'Extremely well shot- and EXTREMELY cute- great colors, focus- everything works for me :) adding to my favorites!', '2008-07-23 12:14:11.000000', NULL, 1),
